    assign out_any[2] = in[2] | in[1];
    assign out_any[3] = in[3] | in[2];
    assign out_any[0] = 1'b0;          // placeholder, not used per spec

    // out_different[i] = in[i] ^ in[i-1] with wrap-around
    // i=3: neighbour is in[0]; i=2: neighbour is in[1]; i=1: neighbour is in[0]
    // out_different[0] uses in[0] ^ in[3] (wrap-around)
