Prob096_review2015_fsmseq.code:
module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states to cover the sequence 1101 detection
    // State 0: Idle (no partial match)
    // State 1: First '1' matched
    // State 2: '11' matched
    // State 3: '110' matched
    typedef enum logic [1:0] {
        S0_IDLE   = 2'b00,
        S1_1      = 2'b01,
        S2_11     = 2'b10,
        S3_110    = 2'b11
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S0_IDLE;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            S0_IDLE: begin
                if (data == 1'b1)
                    next_state = S1_1;
                else
                    next_state = S0_IDLE;
            end
            S1_1: begin
                if (data == 1'b1)
                    next_state = S2_11;
                else
                    next_state = S0_IDLE;
            end
            S2_11: begin
                if (data == 1'b0)
                    next_state = S3_110;
                else
                    next_state = S1_1; // overlapping: '111' -> last '1' is start of new sequence
            end
            S3_110: begin
                if (data == 1'b1)
                    next_state = S0_IDLE; // sequence 1101 fully detected
                else
                    next_state = S0_IDLE;
            end
            default: next_state = S0_IDLE;
        endcase
    end

    // Output logic: start_shifting goes high when we enter S0_IDLE from S3_110
    // (i.e., the sequence 1101 has been found)
    assign start_shifting = (state == S3_110) && (next_state == S0_IDLE);

endmodule

