module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state [9:0],
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // Internal wires for decoded current state signals
    wire cur_S, cur_S1, cur_S11, cur_S110, cur_B0, cur_B1, cur_B2, cur_B3, cur_Count, cur_Wait;

    // One-hot decode: assign each current state wire based on the state vector
    // Encoding: (S, S1, S11, S110, B0, B1, B2, B3, Count, Wait)
    //           (10'b0000000001, 10'b0000000010, 10'b0000000100, 10'b0000001000,
    //            10'b0000010000, 10'b0000100000, 10'b0001000000, 10'b0010000000,
    //            10'b0100000000, 10'b1000000000)
    assign cur_S   = state[0];
    assign cur_S1  = state[1];
    assign cur_S11 = state[2];
    assign cur_S110= state[3];
    assign cur_B0  = state[4];
    assign cur_B1  = state[5];
    assign cur_B2  = state[6];
    assign cur_B3  = state[7];
    assign cur_Count = state[8];
    assign cur_Wait  = state[9];

    // ============================================
    // Next-state logic (one-hot output generation)
    // ============================================

    // B3_next: Assert when next-state is B3
    // From B2 (shift_ena=1) --always--> B3
    assign B3_next = cur_B2;

    // S_next: Assert when next-state is S
    // From S (d=0) --> S
    // From S110 (d=0) --> S
    // From Wait (ack=1) --> S
    assign S_next  = (cur_S   & ~d) |
                     (cur_S110 & ~d) |
                     (cur_Wait &  ack);

    // S1_next: Assert when next-state is S1
    // From S (d=1) --> S1
    assign S1_next = cur_S & d;

    // Count_next: Assert when next-state is Count
    // From B3 (shift_ena=1) --always--> Count
    assign Count_next = cur_B3;

    // Wait_next: Assert when next-state is Wait
    // From Count (counting=1) --done_counting=1--> Wait
    assign Wait_next = cur_Count & done_counting;

    // ============================================
    // Output logic (Moore machine: outputs depend only on current state)
    // ============================================

    // done: Assert when in Wait state (spec: "Wait (done=1)")
    assign done = cur_Wait;

    // counting: Assert when in Count state (spec: "Count (counting=1)")
    assign counting = cur_Count;

    // shift_ena: Assert when in B0, B1, B2, or B3 states (all have shift_ena=1)
    // "B0 (shift_ena=1) --always go to next cycle--> B1"
    // "B1 (shift_ena=1) --always go to next cycle--> B2"
    // "B2 (shift_ena=1) --always go to next cycle--> B3"
    // "B3 (shift_ena=1) --always go to next cycle--> Count"
    assign shift_ena = cur_B0 | cur_B1 | cur_B2 | cur_B3;

endmodule

