    always_comb begin
        case (y)
            3'b000: begin
                y_next = (x == 1'b1) ? 3'b001 : 3'b000;
                z     = 1'b0;
            end
            3'b001: begin
                y_next = (x == 1'b1) ? 3'b100 : 3'b001;
