                z     = 1'b1;
            end
            default: begin
                y_next = 3'b000;
                z     = 1'b0;
            end
        endcase
    end

    // Flip-flops (sequential logic, positive edge triggered)
    always_ff @(posedge clk or posedge reset) begin
