module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 3 bits
    // 3'b000: State A (reset held, or initial)
    // 3'b001: State B (f=1 for one cycle after reset deassertion)
    // 3'b010: State C (monitoring x for pattern 1,0,1)
    // 3'b011: State D1 (g=1, monitoring y, no 0 seen yet)
    // 3'b100: State D2 (g=1, one 0 seen on y, last chance for y=1)
    // 3'b101: State E  (g=0, locked timeout)

    reg [2:0] state, next_state;

    // Output logic
    // f is 1 only in State B
    // g is 1 in State D1 and D2
    assign f = (state == 3'b001);
    assign g = (state == 3'b011 || state == 3'b100);

    // State register (positive edge, active low reset)
    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            state <= 3'b000;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            3'b000: // State A
                next_state = 3'b001; // Go to B on deassert (resetn handled by register)

            3'b001: // State B (f was 1 this cycle)
                next_state = 3'b010; // Move to monitoring state C

            3'b010: // State C (monitoring x for 1,0,1)
                if (x == 1'b1)
                    next_state = 3'b011; // First '1' seen, go to D1
                else if (x == 1'b0)
                    next_state = 3'b010; // Still waiting for the pattern, stay in C
                else
                    next_state = 3'b010; // x==1 again, stay in C (reset pattern or hold)

            3'b011: // State D1 (g=1, fresh start, monitoring y)
                if (y == 1'b1)
                    next_state = 3'b011; // y=1 within cycle, maintain g=1
                else
                    next_state = 3'b100; // y=0 seen, go to D2 (one 0 seen)

            3'b100: // State D2 (g=1, one 0 seen, last chance for y=1)
                if (y == 1'b1)
                    next_state = 3'b011; // y=1 within 2 cycles, maintain g=1 (return to D1)
                else
                    next_state = 3'b101; // y=0 again, timeout, go to E

            3'b101: // State E  (g=0, locked timeout)
                next_state = 3'b101; // Stay in E permanently until reset

            default: next_state = 3'b000;
        endcase
    end

endmodule

