module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [2:0] {
        WALK_LEFT,    // 000
        WALK_RIGHT,   // 001
        FALLING,      // 010
        DIGGING,      // 011
        SPLATTERED    // 100
    } state_t;

    // State register
    state_t state, next_state;

    // Fall counter - tracks how many cycles we've been falling
    logic [4:0] fall_counter, next_fall_counter;

    // Walking direction register - needed to know direction during digging/fall recovery
    logic walking_left, next_walking_left;

    // Outputs (Moore machine)
    assign walk_left   = (state == WALK_LEFT) & ~(state == SPLATTERED);
    assign walk_right  = (state == WALK_RIGHT) & ~(state == SPLATTERED);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING) & ~(state == SPLATTERED);

    // State register (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            walking_left <= 1'b1;
            fall_counter <= 5'd0;
        end else begin
            state <= next_state;
            walking_left <= next_walking_left;
            fall_counter <= next_fall_counter;
        end
    end

    // Next-state logic
    always_comb begin
        // Default values
        next_state = state;
        next_walking_left = walking_left;
        next_fall_counter = fall_counter;

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Ground disappears - start falling
                    next_state = FALLING;
                    next_fall_counter = 5'd1;
                end else if (dig) begin
                    // Start digging when on ground
                    next_state = DIGGING;
                end else if (bump_right) begin
                    // Bumped on right -> walk left
                    // If also bumped on left, switch directions (walk right)
                    if (bump_left) begin
                        next_state = WALK_RIGHT;
                        next_walking_left = 1'b0;
                    end else begin
                        // Only bumped on right - already walking left, so stay walking left
                        next_state = WALK_LEFT;
                    end
                end else if (bump_left) begin
                    // Bumped on left -> walk right
                    next_state = WALK_RIGHT;
                    next_walking_left = 1'b0;
                end
                // If none of the above, stay walking left
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    next_fall_counter = 5'd1;
                end else if (dig) begin
                    next_state = DIGGING;
                end else if (bump_left) begin
                    // Bumped on left -> walk right
                    // If also bumped on right, switch directions (walk left)
                    if (bump_right) begin
                        next_state = WALK_LEFT;
                        next_walking_left = 1'b1;
                    end else begin
                        // Only bumped on left - already walking right, stay walking right
                        next_state = WALK_RIGHT;
                    end
                end else if (bump_right) begin
                    // Bumped on right -> walk left
                    next_state = WALK_LEFT;
                    next_walking_left = 1'b1;
                end
            end

            FALLING: begin
                if (!ground) begin
                    // Still falling, increment counter
                    next_fall_counter = fall_counter + 5'd1;
                    // No state change yet
                end else begin
                    // Ground reappears!
                    if (fall_counter > 5'd20) begin
                        // Fell for more than 20 cycles -> splatter
                        next_state = SPLATTERED;
                    end else begin
                        // Fell for 20 cycles or less -> resume walking
                        // Resume in same direction as before the fall
                        if (walking_left) begin
                            next_state = WALK_LEFT;
                        end else begin
                            next_state = WALK_RIGHT;
                        end
                    end
                end
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached other side (ground=0), fall
                    next_state = FALLING;
                    next_fall_counter = 5'd1;
                end else if (!dig) begin
                    // Stop digging when told to stop
                    // Resume walking in current direction
                    // (walking_left already tracks this)
                    next_state = walking_left ? WALK_LEFT : WALK_RIGHT;
                end
                // If still digging and on ground, stay digging
            end

            SPLATTERED: begin
                // Stay splattered forever
                next_state = SPLATTERED;
            end
        endcase
    end

endmodule
